-- Flashcard top-up: Biology|OCR B|gcse — brings each topic up to 30 cards.
-- Generated by scripts/build-flashcard-topup.js from flashcards/topup/src/biology-ocr-b-gcse.txt
-- Safe to re-run: skips fronts already present and never takes a topic past 30.
WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'What is DNA?', 'Deoxyribonucleic acid: a double-stranded polymer of nucleotides that stores the genetic information of an organism.', 1),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'What is a gene?', 'A short section of DNA that codes for a specific sequence of amino acids, making a particular protein.', 2),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'What is a genome?', 'The entire genetic material of an organism, including all its genes and its non-coding DNA.', 3),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'What is a chromosome?', 'A long, coiled molecule of DNA packaged with proteins, found in the nucleus of eukaryotic cells.', 4),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'What is an allele?', 'A different version of the same gene, e.g. an allele for blue eyes and an allele for brown eyes.', 5),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'Where is the genetic material found in a eukaryotic cell?', 'In the nucleus, packaged into chromosomes.', 6),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'Where is the genetic material found in a prokaryotic (bacterial) cell?', 'Free in the cytoplasm as a single loop of DNA, plus small rings called plasmids; there is no nucleus.', 7),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'How many chromosomes are in a normal human body cell?', '46 chromosomes, arranged in 23 pairs; one of each pair comes from each parent.', 8),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'How many chromosomes are in a human gamete?', '23 chromosomes (one from each pair), so gametes are haploid.', 9),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'Put in order of size, smallest first: chromosome, gene, nucleus, base.', 'Base, gene, chromosome, nucleus.', 10),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'What is a nucleotide made of?', 'A phosphate group, a deoxyribose sugar and one of four nitrogenous bases.', 11),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'Name the four bases in DNA.', 'Adenine (A), thymine (T), cytosine (C) and guanine (G).', 12),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'State the complementary base-pairing rules in DNA.', 'A always pairs with T, and C always pairs with G.', 13),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'Describe the structure of DNA.', 'Two strands twisted into a double helix; each has a sugar–phosphate backbone with bases attached; bases pair A–T and C–G, held by hydrogen bonds.', 14),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'What holds the two strands of DNA together?', 'Weak hydrogen bonds between complementary base pairs.', 15),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'Why is DNA described as a polymer?', 'It is a long chain made of many repeating units (monomers) called nucleotides.', 16),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'A DNA strand reads ATCGGA. What is the complementary strand?', 'TAGCCT.', 17),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'A DNA sample contains 30% adenine. What percentage is guanine?', 'A = T = 30%, so A + T = 60%; C + G = 40%, so guanine = 20%.', 18),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', '(Higher) How does a gene code for a protein?', '(Higher) The order of bases determines the order of amino acids; each triplet of three bases codes for one amino acid.', 19),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'A gene contains 90 bases. What is the maximum number of amino acids it can code for?', '3 bases code for 1 amino acid, so 90 ÷ 3 = 30 amino acids.', 20),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'Why do different proteins have different functions?', 'Different amino acid sequences make the protein fold into a different shape, and shape determines function (e.g. enzyme active sites).', 21),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'What is non-coding DNA?', 'DNA that does not code for amino acids; some of it controls when and where genes are switched on.', 22),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'What did the Human Genome Project achieve?', 'It sequenced the ~3 billion base pairs of human DNA (1990–2003) and identified about 20 000 protein-coding genes.', 23),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'Give three uses of human genome data.', 'Identifying alleles linked to inherited disease, personalised medicine (choosing drugs/doses), tracing ancestry and evolution, and predicting disease risk.', 24),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'Give two concerns about sequencing people''s genomes.', 'Privacy of genetic data, possible discrimination by insurers or employers, cost, and anxiety from risk results that may never develop.', 25),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'What is a mutation?', 'A random change in the base sequence of DNA.', 26),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'Name three things that increase the rate of mutation.', 'UV light, ionising radiation (X-rays, gamma rays) and some chemicals such as tar in tobacco smoke.', 27),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'Why do most mutations have no effect on the phenotype?', 'They occur in non-coding DNA, or the new triplet codes for the same amino acid, or the protein''s shape and function are unchanged.', 28),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', '(Higher) Why does an insertion or deletion of one base usually have a big effect?', '(Higher) It shifts the reading frame, so every triplet after it changes, altering many amino acids and usually producing a non-functional protein.', 29),
  ('Biology', 'OCR B', 'gcse', 'B1.1', 'The genome and what it does', 'What determines an organism''s characteristics (phenotype)?', 'Its genome (the alleles it has) interacting with its environment; most characteristics are affected by both.', 30),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'What is a gamete?', 'A sex cell (sperm or egg) containing one set of chromosomes (haploid; 23 in humans).', 1),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'What is a zygote?', 'The diploid cell formed when two gametes fuse at fertilisation.', 2),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'Why must gametes contain half the normal number of chromosomes?', 'So that when two fuse at fertilisation the diploid number (46) is restored and stays constant each generation.', 3),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'What is the difference between haploid and diploid?', 'Haploid cells have one set of chromosomes (gametes); diploid cells have two sets, in pairs (body cells).', 4),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'Define genotype.', 'The combination of alleles an organism has for a gene, e.g. Bb.', 5),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'Define phenotype.', 'The observable characteristic that results from the genotype interacting with the environment, e.g. brown eyes.', 6),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'What does homozygous mean?', 'Having two identical alleles for a gene, e.g. BB or bb.', 7),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'What does heterozygous mean?', 'Having two different alleles for a gene, e.g. Bb.', 8),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'What is a dominant allele?', 'An allele that is expressed in the phenotype even if only one copy is present; shown by a capital letter.', 9),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'What is a recessive allele?', 'An allele expressed only when two copies are present (homozygous recessive); shown by a lower-case letter.', 10),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'Two heterozygous parents (Bb × Bb) have children. What is the genotype ratio?', '1 BB : 2 Bb : 1 bb.', 11),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'Two heterozygous parents (Bb × Bb) have children. What is the phenotype ratio?', '3 dominant : 1 recessive.', 12),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'What is the probability that a child of Bb × Bb parents is bb?', '1 in 4, i.e. 0.25 or 25%.', 13),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'A cross of Bb × bb is carried out. What is the expected phenotype ratio?', '1 dominant : 1 recessive (50% Bb, 50% bb).', 14),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'How do you draw a Punnett square?', 'Write one parent''s gametes along the top and the other''s down the side, then fill each box with the combined offspring genotype.', 15),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'What are the human sex chromosomes for females and males?', 'Females are XX; males are XY.', 16),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'Why is the chance of a baby being a boy 50%?', 'All eggs carry X; half of sperm carry X and half carry Y, so XX and XY are equally likely.', 17),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'Which parent''s gamete determines the sex of a child?', 'The father''s sperm, because it can carry either an X or a Y chromosome.', 18),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'Why do most characteristics not follow simple single-gene ratios?', 'Most are controlled by many genes acting together and are also influenced by the environment.', 19),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'What is continuous variation?', 'Variation with a range of values and no distinct groups, usually forming a normal distribution, e.g. height or mass; usually polygenic plus environment.', 20),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'What is discontinuous variation?', 'Variation in distinct categories with no intermediates, e.g. blood group; usually controlled by one or a few genes.', 21),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'How do identical twins show the effect of environment?', 'They share the same genome, so differences between them (e.g. mass, scars) must be caused by the environment.', 22),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'What causes cystic fibrosis and how is it inherited?', 'A recessive allele of a membrane-protein gene; a person must inherit two faulty alleles (cc). It causes thick, sticky mucus in lungs and digestive system.', 23),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'Two carriers of cystic fibrosis (Cc × Cc) have a child. What are the chances?', '25% affected (cc), 50% carrier (Cc), 25% unaffected non-carrier (CC).', 24),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'What is a carrier?', 'A heterozygous person with one recessive disease allele who does not have the disorder but can pass the allele on.', 25),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'How is Huntington''s disease inherited?', 'It is caused by a dominant allele, so only one faulty allele is needed; one affected heterozygous parent gives a 50% chance per child.', 26),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'What is pre-implantation genetic diagnosis (PGD)?', 'IVF embryos are tested for a faulty allele before implantation, and only unaffected embryos are implanted.', 27),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'Name two forms of prenatal genetic testing and one risk.', 'Amniocentesis and chorionic villus sampling (CVS); both carry a small risk of miscarriage.', 28),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'Give two arguments for genetic testing of embryos.', 'Reduces suffering from serious disorders and allows parents an informed choice about the pregnancy.', 29),
  ('Biology', 'OCR B', 'gcse', 'B1.2', 'How genetic information is inherited', 'Give two arguments against genetic testing of embryos.', 'Embryos are destroyed or pregnancies terminated, fears of "designer babies", possible discrimination against disabled people, false results and cost.', 30),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'What is selective breeding?', 'Humans choose parents with desired characteristics and breed them over many generations so the offspring show the trait more strongly.', 1),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'Outline the steps of selective breeding.', 'Choose parents with the desired trait, breed them, select the offspring showing it most strongly, breed these, and repeat over many generations.', 2),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'Give two examples of selective breeding and the trait selected.', 'Dairy cows for high milk yield; wheat for large grain and disease resistance; dogs for gentle temperament.', 3),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'What is a disadvantage of selective breeding (inbreeding)?', 'Reduces genetic variation, so harmful recessive alleles combine more often and the population is more vulnerable to new diseases.', 4),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'What is genetic engineering?', 'Changing an organism''s genome, usually by inserting a gene from another organism, to give a desired characteristic.', 5),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'What is a genetically modified organism (GMO)?', 'An organism whose genome has been altered by genetic engineering.', 6),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'What do restriction enzymes do?', 'Cut DNA at specific base sequences, often leaving single-stranded "sticky ends".', 7),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'What does DNA ligase do?', 'Joins DNA fragments together by sealing the sugar–phosphate backbone, e.g. inserting a gene into a plasmid.', 8),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'What is a vector in genetic engineering?', 'Something that carries the new gene into the host cell, such as a bacterial plasmid or a virus.', 9),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'Why must the same restriction enzyme cut both the gene and the plasmid?', 'It produces complementary sticky ends that can base-pair, so the gene fits into the plasmid.', 10),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'Describe how human insulin is produced using bacteria.', 'Cut out insulin gene with restriction enzyme; cut plasmid with same enzyme; join with ligase; insert into bacterium; grow in fermenter; purify the insulin produced.', 11),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'What is a marker gene used for in genetic engineering?', 'A gene such as antibiotic resistance, used to identify which cells have successfully taken up the recombinant plasmid.', 12),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'What is Bt maize?', 'A GM crop containing a gene from Bacillus thuringiensis that makes a toxin killing insect pests, so less pesticide is needed.', 13),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'What is golden rice?', 'GM rice that makes beta-carotene (used to make vitamin A), to reduce vitamin A deficiency and blindness.', 14),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'Why are some crops made herbicide-resistant?', 'Farmers can spray herbicide to kill weeds without killing the crop, increasing yield.', 15),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'Give two benefits of GM crops.', 'Higher yields, less pesticide use, added nutrients, and crops that grow in drought or poor soils.', 16),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'Give two concerns about GM crops.', 'Genes may spread to wild relatives, pests may evolve resistance, unknown long-term effects, reduced biodiversity, and seed patents giving companies power over farmers.', 17),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'Why might pests become resistant to Bt crops?', 'Natural selection: pests with resistance alleles survive the toxin and reproduce, passing resistance on.', 18),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'What is gene therapy?', 'Inserting a working copy of a gene into a patient''s cells, using a vector such as a modified virus, to treat a genetic disorder.', 19),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'Give two problems with gene therapy.', 'Immune reaction to the viral vector, the gene may insert in the wrong place, and treated cells are replaced so effects may not last.', 20),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'What is the difference between somatic and germline gene therapy?', 'Somatic changes body cells of one patient and is not inherited; germline changes gametes or embryos, so changes are passed to future generations.', 21),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'Why is germline gene editing controversial?', 'Changes are inherited by future generations who cannot consent, and long-term or off-target effects are unknown.', 22),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'What is CRISPR-Cas9?', 'A precise gene-editing tool that cuts DNA at a chosen sequence so a gene can be removed, corrected or replaced.', 23),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'What are stem cells?', 'Unspecialised cells that can divide and differentiate into different types of specialised cell.', 24),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'Compare embryonic and adult stem cells.', 'Embryonic stem cells can become any cell type; adult stem cells (e.g. bone marrow) can only become a limited range of cell types.', 25),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'Give one ethical issue and one alternative to using embryonic stem cells.', 'Embryos are destroyed, which some see as ending a potential life; induced pluripotent stem cells reprogrammed from adult cells avoid this and avoid rejection.', 26),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'How is a plant cloned by tissue culture?', 'Small pieces of plant tissue are grown on sterile agar containing nutrients and hormones, producing many genetically identical plants.', 27),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'How was Dolly the sheep cloned (adult cell cloning)?', 'The nucleus from an adult body cell was put into an egg cell with its nucleus removed; an electric shock started division and the embryo was implanted in a surrogate.', 28),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'How is a DNA profile produced and used?', 'DNA is cut into fragments and separated by gel electrophoresis to give a unique band pattern; used in forensics, paternity tests and identifying victims.', 29),
  ('Biology', 'OCR B', 'gcse', 'B1.3', 'Gene technology', 'Give two limitations of DNA profiling evidence.', 'Samples can be contaminated or degraded, identical twins share profiles, and DNA at a scene does not show how or when it got there.', 30),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'How does the WHO define health?', 'A state of complete physical, mental and social well-being, not merely the absence of disease.', 1),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'What is a communicable disease?', 'A disease caused by a pathogen that can be passed from one person or organism to another, e.g. measles.', 2),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'What is a non-communicable disease?', 'A disease that cannot be spread between people, caused by lifestyle, genes or environment, e.g. cardiovascular disease.', 3),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'What is a pathogen?', 'A microorganism that causes infectious disease.', 4),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'Name the four main groups of pathogen.', 'Bacteria, viruses, fungi and protists.', 5),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'Give one disease caused by a bacterium.', 'Tuberculosis (TB), cholera, salmonella food poisoning or gonorrhoea.', 6),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'Give one disease caused by a virus.', 'Influenza, HIV, measles, COVID-19 or tobacco mosaic virus (plants).', 7),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'Give one disease caused by a fungus.', 'Athlete''s foot (humans) or rose black spot (plants).', 8),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'Give one disease caused by a protist and its vector.', 'Malaria, caused by Plasmodium, spread by the Anopheles mosquito.', 9),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'Describe the structure of a bacterium.', 'A single prokaryotic cell with cell wall, membrane, cytoplasm, a loop of DNA and plasmids, but no nucleus.', 10),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'How do viruses reproduce?', 'They enter host cells and use them to make many copies of the virus, then the cell bursts, releasing new viruses.', 11),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'Why are viruses not considered living cells?', 'They have no cytoplasm or cell structures and can only reproduce inside a host cell.', 12),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'How do bacteria make us feel ill?', 'They reproduce rapidly and release toxins that damage tissues.', 13),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'Give two ways pathogens make a person ill.', 'By damaging or destroying cells directly (e.g. viruses bursting cells) and by producing toxins (e.g. cholera toxin in the gut).', 14),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'How is influenza spread?', 'In airborne droplets from coughs and sneezes.', 15),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'How is cholera spread?', 'Through water or food contaminated with faeces containing the bacterium.', 16),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'How is HIV spread?', 'Through exchange of body fluids, e.g. unprotected sex, shared needles, or mother to baby.', 17),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'How is athlete''s foot spread?', 'By direct contact with the fungus, e.g. on shared towels or wet floors.', 18),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'What is a vector?', 'An organism that carries a pathogen from one host to another without getting the disease itself, e.g. a mosquito.', 19),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'How is tuberculosis spread and what does it affect?', 'In airborne droplets; the bacterium mainly damages the lungs, causing coughing (sometimes blood) and weight loss.', 20),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'How does HIV lead to AIDS?', 'HIV infects and destroys white blood cells (T-helper cells), weakening the immune system so other infections take hold.', 21),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'Explain how one disease can make someone more likely to get another.', 'e.g. HIV weakens the immune system, increasing risk of TB; physical illness can also trigger mental ill-health such as depression.', 22),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'How does tobacco mosaic virus affect plants?', 'Causes a mosaic pattern of discoloured leaves, reducing chlorophyll so photosynthesis and growth decrease.', 23),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'How does rose black spot affect plants?', 'Fungus causes black spots on leaves, which yellow and drop off, reducing photosynthesis; spores spread by wind and water.', 24),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'How can a plant pathogen be spread?', 'By wind, water, soil, contact between plants, and insect vectors such as aphids.', 25),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'Give three lifestyle causes of non-communicable disease.', 'Smoking, excessive alcohol, poor diet and lack of exercise.', 26),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'Give two environmental causes of non-communicable disease.', 'UV radiation (skin cancer), air pollution (asthma, lung disease) and asbestos (mesothelioma).', 27),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'Give an example of a genetic cause of non-communicable disease.', 'Inheriting faulty alleles, e.g. sickle-cell anaemia or BRCA1 alleles raising breast cancer risk.', 28),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'Why can stress increase the risk of communicable disease?', 'Severe or long-term stress weakens the immune system, making infection more likely.', 29),
  ('Biology', 'OCR B', 'gcse', 'B2.1', 'Causes of disease', 'What is the incubation period?', 'The time between infection with a pathogen and the appearance of symptoms, while the pathogen multiplies.', 30),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'Name four non-specific defences of the human body.', 'Skin, mucus and cilia in airways, stomach acid, and enzymes (lysozyme) in tears and saliva; also blood clotting.', 1),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'How does the skin protect against pathogens?', 'Acts as a tough physical barrier and secretes antimicrobial substances (sebum); skin bacteria also compete with pathogens.', 2),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'How do mucus and cilia protect the airways?', 'Mucus traps pathogens; cilia waft the mucus up to the throat where it is swallowed.', 3),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'How does the stomach protect against pathogens?', 'It produces hydrochloric acid (about pH 2) that kills most pathogens in food and swallowed mucus.', 4),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'How do tears protect the eyes?', 'They contain lysozyme, an enzyme that breaks down bacterial cell walls.', 5),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'How does blood clotting help defend the body?', 'Platelets help form a clot and scab that seals wounds, stopping pathogens entering.', 6),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'What is an antigen?', 'A unique molecule (usually protein) on the surface of a pathogen that the immune system recognises as foreign.', 7),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'What is phagocytosis?', 'A phagocyte (white blood cell) engulfs a pathogen and digests it with enzymes.', 8),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'Is phagocytosis specific or non-specific?', 'Non-specific: phagocytes engulf any foreign cell or particle.', 9),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'What do lymphocytes produce?', 'Antibodies that are complementary in shape to a specific antigen.', 10),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'How do antibodies help destroy pathogens?', 'They bind to specific antigens, clumping pathogens together and marking them so phagocytes can engulf them; some neutralise toxins.', 11),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'Why is an antibody specific to one antigen?', 'Its binding site has a shape complementary to only one antigen, like a lock and key.', 12),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'What are memory cells?', 'Lymphocytes that remain in the blood after an infection and can rapidly produce the right antibodies if the same pathogen returns.', 13),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'Why do you rarely catch measles twice?', 'Memory cells cause a faster, larger antibody response on re-infection, destroying the pathogen before symptoms develop.', 14),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'Compare the primary and secondary immune responses.', 'Secondary response is faster, produces far more antibodies and lasts longer, because memory cells already exist.', 15),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'Why do you feel ill during a first infection?', 'Lymphocytes take time to make enough of the right antibody, so pathogens multiply and cause symptoms first.', 16),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'What does a vaccine contain?', 'Dead, weakened or inactive pathogens, or harmless parts of them such as antigens.', 17),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'Describe how a vaccine gives immunity.', 'Antigens in the vaccine trigger lymphocytes to make antibodies and memory cells; on later infection memory cells respond rapidly so the person does not become ill.', 18),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'What is herd immunity?', 'When a large proportion of a population is vaccinated, the pathogen cannot spread easily, protecting unvaccinated people too.', 19),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'Why is herd immunity important?', 'It protects people who cannot be vaccinated, such as newborn babies and people with weak immune systems.', 20),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'Why do new flu vaccines need to be produced each year?', 'The flu virus mutates, changing its antigens, so existing antibodies and memory cells no longer recognise it.', 21),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'What is the difference between active and passive immunity?', 'Active: your own lymphocytes make antibodies (long-lasting). Passive: ready-made antibodies are given, e.g. via breast milk (short-lived).', 22),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'Give two risks or drawbacks of vaccination.', 'Mild side-effects such as fever or soreness; rarely severe allergic reactions; they do not work for everyone.', 23),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'How do white blood cells counter toxins?', 'Some lymphocytes produce antitoxins that bind to and neutralise toxins.', 24),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'Name three physical defences of plants.', 'Cellulose cell walls, a waxy cuticle on leaves and bark or dead cells on stems.', 25),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'How does a waxy cuticle protect a plant?', 'It forms a barrier that stops pathogens reaching the cells underneath.', 26),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'Give an example of a plant chemical defence.', 'Antibacterial chemicals such as those in mint and witch hazel, or poisons that deter herbivores.', 27),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'Give an example of a plant mechanical defence.', 'Thorns and hairs deter animals; leaves that droop or curl when touched; mimicry to look poisonous.', 28),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'Why does bark help defend trees?', 'It is a tough layer of dead cells that blocks entry, and when it falls off it takes pathogens with it.', 29),
  ('Biology', 'OCR B', 'gcse', 'B2.2', 'Defending against pathogens', 'How do plants limit the spread of a pathogen once infected?', 'They can seal off infected areas, e.g. by thickening cell walls or killing cells around the infection.', 30),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'Give four public-health measures that reduce the spread of infection.', 'Clean water and sewage treatment, hand washing, vaccination, isolating infected people, vector control and food hygiene.', 1),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'How does hand washing reduce the spread of disease?', 'Soap removes pathogens from hands and disrupts the membranes of bacteria and some viruses, preventing transfer.', 2),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'How does sewage treatment and clean water reduce disease?', 'It prevents waterborne pathogens such as cholera bacteria reaching drinking water.', 3),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'How does covering coughs and sneezes reduce spread?', 'It stops infected airborne droplets reaching other people.', 4),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'What is quarantine?', 'Isolating people or animals that may be infected so they cannot pass the pathogen on.', 5),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'How can malaria be controlled?', 'Mosquito nets, insect repellent, insecticides, draining standing water where mosquitoes breed, and antimalarial drugs.', 6),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'How does cooking food thoroughly prevent disease?', 'Heat kills bacteria such as Salmonella and E. coli.', 7),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'How do condoms reduce disease spread?', 'They stop exchange of body fluids, preventing sexually transmitted infections such as HIV and gonorrhoea.', 8),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'How can the spread of plant diseases be reduced?', 'Remove and destroy infected plants, control insect vectors, rotate crops, use resistant varieties and apply fungicides.', 9),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'How was smallpox eradicated?', 'A global vaccination programme reduced susceptible people until the virus could no longer spread (declared eradicated in 1980).', 10),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'What is an epidemic?', 'A widespread outbreak of a disease in a particular region or population at a particular time.', 11),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'What is a pandemic?', 'An epidemic that spreads across many countries or worldwide, e.g. COVID-19.', 12),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'What are antibiotics?', 'Medicines that kill bacteria or stop their growth inside the body without harming body cells.', 13),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'Why don''t antibiotics treat viral infections such as flu?', 'Viruses live inside host cells and lack the bacterial structures (cell walls, enzymes) that antibiotics target.', 14),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'What is an antiseptic?', 'A chemical that kills microorganisms on the outside of the body or on surfaces, e.g. on skin before surgery.', 15),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'Explain how antibiotic resistance develops.', 'A random mutation makes some bacteria resistant; antibiotic kills the others; resistant bacteria survive, reproduce and pass on the allele, so resistance spreads (natural selection).', 16),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', '(Higher) How can bacteria spread resistance quickly between each other?', '(Higher) Resistance genes on plasmids can be passed between bacteria, even of different species.', 17),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'What is MRSA?', 'A strain of Staphylococcus aureus bacteria resistant to many antibiotics, a problem in hospitals.', 18),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'Give three ways to slow the development of antibiotic resistance.', 'Only prescribe antibiotics when needed (not for viruses), finish the full course, reduce use in farming, and good hospital hygiene.', 19),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'Why should patients complete a full course of antibiotics?', 'To kill all the bacteria so none survive to mutate and form resistant strains.', 20),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'Why is overuse of antibiotics in farming a problem?', 'Routine use exposes many bacteria to antibiotics, selecting for resistant strains that can spread to humans.', 21),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'Why is it difficult to develop new antibiotics?', 'It is slow and expensive, and bacteria may evolve resistance to them quickly.', 22),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'List the main stages in developing a new medicine.', 'Discovery, preclinical testing on cells/tissues and animals, clinical trials (phase 1, 2, 3), then approval and ongoing monitoring.', 23),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'What is tested in preclinical testing?', 'Toxicity, efficacy and dose of a candidate drug, using cell cultures, tissues and animals.', 24),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'What happens in a phase 1 clinical trial?', 'A low dose is given to a small group of healthy volunteers to test safety and side-effects.', 25),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'What happens in phase 2 and 3 clinical trials?', 'The drug is given to increasing numbers of patients with the disease to test how well it works and find the optimum dose.', 26),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'What is a placebo?', 'A dummy treatment that looks like the drug but has no active ingredient, used as a control.', 27),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'What is a double-blind trial?', 'Neither patients nor doctors know who receives the drug or the placebo, removing bias.', 28),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'What is the purpose of a control group in a drug trial?', 'To compare with the treated group so any effect can be attributed to the drug, not other factors.', 29),
  ('Biology', 'OCR B', 'gcse', 'B2.3', 'Preventing the spread of infections', 'Why do drug trials use large sample sizes?', 'To make results more reliable and reveal rare side-effects, and make chance effects less likely.', 30),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'Name four ways of identifying the cause of an infection.', 'Symptoms and history, microscopy of samples, culturing microbes on agar, antigen/antibody tests, and DNA tests such as PCR.', 1),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'How can microscopy help identify a pathogen?', 'Pathogens such as Plasmodium in blood smears or fungal hyphae can be seen and identified by their appearance.', 2),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'How can bacteria from a sample be identified?', 'Culture them on agar and examine colony shape and colour, cell shape and staining (e.g. Gram stain), or use biochemical and DNA tests.', 3),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'How do DNA tests (PCR) identify pathogens?', 'They detect DNA or RNA sequences specific to one pathogen, giving a precise and sensitive identification.', 4),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'How does a lateral flow (antigen) test work?', 'Antibodies on the strip bind to a pathogen''s specific antigens; a coloured line appears if the antigen is present.', 5),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'Why is identifying the specific pathogen important?', 'So the correct treatment is given, e.g. the right antibiotic for bacteria, and spread can be controlled.', 6),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'How can plant diseases be identified?', 'Observe symptoms (spots, discoloration, stunted growth), look at the pattern of affected plants, use a gardening manual, lab tests or testing kits with antibodies.', 7),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'What is a monoclonal antibody?', 'Many identical antibodies produced by clones of a single type of lymphocyte, all specific to one antigen.', 8),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'Outline how monoclonal antibodies are produced.', 'Inject mouse with antigen; collect antibody-producing lymphocytes; fuse with tumour cells to make hybridomas; clone the right hybridoma; collect and purify the antibodies.', 9),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'What is a hybridoma?', 'A cell formed by fusing a lymphocyte with a tumour cell; it divides rapidly and produces one specific antibody.', 10),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'Why are lymphocytes fused with tumour cells?', 'Lymphocytes make antibodies but do not divide; tumour cells divide indefinitely, so the hybrid does both.', 11),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'How do monoclonal antibodies work in a pregnancy test?', 'Antibodies on the stick bind to the hormone hCG in urine; a coloured line appears if hCG is present.', 12),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'How can monoclonal antibodies help treat cancer?', 'They bind to antigens on cancer cells, carrying drugs, toxins or radioactive substances directly to them, or trigger the immune system to attack them.', 13),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'Give two advantages of monoclonal antibodies.', 'Highly specific, so they target only particular cells and cause less harm to healthy cells; can be produced in large quantities.', 14),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'Give two disadvantages of monoclonal antibodies.', 'More side-effects than expected, expensive to develop, and use of mice raises ethical concerns.', 15),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'Name three drugs originally from natural sources.', 'Aspirin (willow bark), digitalis (foxglove) and penicillin (Penicillium mould).', 16),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'Who discovered penicillin and how?', 'Alexander Fleming (1928) noticed bacteria did not grow around a Penicillium mould contaminating a culture plate.', 17),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'What do antiviral drugs do?', 'Slow viral replication inside cells, e.g. oseltamivir for flu; they do not usually destroy the virus.', 18),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'What is aseptic technique?', 'Methods to prevent contamination of cultures by unwanted microbes and to protect the worker, e.g. flaming loops, sterile equipment, opening lids briefly.', 19),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'Why are inoculating loops passed through a Bunsen flame?', 'To sterilise them by killing any microorganisms on them before use.', 20),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'Why are agar plates taped but not fully sealed?', 'Fully sealing could create anaerobic conditions that encourage harmful anaerobic bacteria; tape stops the lid coming off.', 21),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'Why are school cultures incubated at no more than 25 °C?', 'To reduce the chance of growing human pathogens, which grow best near 37 °C.', 22),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'Describe how to test the effect of antibiotics on bacteria (PAG 7).', 'Spread bacteria on agar aseptically, add paper discs soaked in different antibiotics plus a water control, incubate at 25 °C, then measure clear zones of inhibition.', 23),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'What is a zone of inhibition?', 'The clear area around an antibiotic or antiseptic disc where bacteria have not grown.', 24),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'How do you calculate the area of a zone of inhibition?', 'Area = πr², where r is the radius (half the measured diameter).', 25),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'A clear zone has a diameter of 12 mm. Calculate its area.', 'r = 6 mm; area = π × 6² ≈ 113 mm².', 26),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'What does a larger zone of inhibition show?', 'The antibiotic or antiseptic is more effective at killing or inhibiting the bacteria.', 27),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'Why is a disc soaked in sterile water included?', 'As a control, to show that any clear zone is caused by the antibiotic, not the disc.', 28),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'How are used agar plates disposed of safely?', 'They are sterilised in an autoclave (about 121 °C) before disposal, without being opened.', 29),
  ('Biology', 'OCR B', 'gcse', 'B2.4', 'Identifying the cause of an infection', 'Why can the same symptoms make diagnosis difficult?', 'Different pathogens can cause similar symptoms (e.g. fever, cough), so tests are needed to identify the specific cause.', 30),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'What is a risk factor?', 'Something that increases the probability of a person developing a particular disease, linked to lifestyle, environment or genes.', 1),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'Give two diseases linked to smoking.', 'Lung cancer, COPD (bronchitis/emphysema), cardiovascular disease, and low birth weight babies.', 2),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'Give two diseases linked to excessive alcohol.', 'Liver cirrhosis, liver cancer and brain damage; also fetal alcohol syndrome in pregnancy.', 3),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'Give two diseases linked to obesity.', 'Type 2 diabetes, cardiovascular disease, osteoarthritis and some cancers.', 4),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'How is BMI calculated?', 'BMI = mass (kg) ÷ height² (m²).', 5),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'Calculate the BMI of a person with mass 80 kg and height 1.6 m.', 'BMI = 80 ÷ 1.6² = 80 ÷ 2.56 = 31.3 (obese, BMI over 30).', 6),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'What is waist-to-hip ratio and why is it used?', 'Waist circumference ÷ hip circumference; it shows fat around the abdomen, which is linked to higher risk of CVD and type 2 diabetes.', 7),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'What is cardiovascular disease (CVD)?', 'Diseases of the heart and blood vessels, e.g. coronary heart disease, heart attack and stroke.', 8),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'What is atherosclerosis?', 'Build-up of fatty plaques in artery walls, narrowing them and restricting blood flow.', 9),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'How does a blocked coronary artery cause a heart attack?', 'Heart muscle receives less oxygen and glucose for respiration, so cells die.', 10),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'Give four risk factors for CVD.', 'Smoking, high saturated fat and cholesterol, high salt (high blood pressure), lack of exercise, obesity and family history.', 11),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'How does high salt intake increase CVD risk?', 'It raises blood pressure, which damages artery walls and promotes plaque formation.', 12),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'How does smoking increase CVD risk?', 'Nicotine raises heart rate and blood pressure; carbon monoxide reduces oxygen carried by red blood cells; chemicals damage artery walls.', 13),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'How does exercise reduce the risk of CVD?', 'It helps control body mass, lowers blood pressure and cholesterol, and strengthens heart muscle.', 14),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'What is cancer?', 'A group of diseases caused by uncontrolled cell division, forming a tumour.', 15),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'What causes cancer at the cellular level?', 'Mutations in genes controlling cell division, so cells divide uncontrollably.', 16),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'What is the difference between benign and malignant tumours?', 'Benign tumours stay in one place, contained; malignant tumours invade tissues and spread to form secondary tumours.', 17),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'What is metastasis?', 'Cells from a malignant tumour break off and spread in the blood or lymph to form secondary tumours elsewhere.', 18),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'What is a carcinogen? Give an example.', 'Something that causes cancer, e.g. tar in tobacco smoke, asbestos, UV light or ionising radiation.', 19),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'How do UV rays increase skin cancer risk?', 'UV damages DNA in skin cells, causing mutations that can lead to uncontrolled division (melanoma).', 20),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'Give a genetic risk factor for cancer.', 'Inheriting faulty BRCA1 or BRCA2 alleles greatly increases breast and ovarian cancer risk.', 21),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'Give two lifestyle factors linked to bowel cancer.', 'Low-fibre diet, high processed or red meat intake, lack of exercise, alcohol and smoking.', 22),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'Why do some people with risk factors never get the disease?', 'Risk factors only increase probability; disease depends on many interacting factors including genes and chance.', 23),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'What is a correlation?', 'A relationship between two variables, so that as one changes the other tends to change too.', 24),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'Why does a correlation not prove causation?', 'The link may be due to chance or a third factor; a causal mechanism must be found.', 25),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'What evidence makes a causal link between a factor and a disease more convincing?', 'A plausible biological mechanism, a dose–response relationship, cause preceding effect, and consistent results across large studies.', 26),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'Why are large samples used in health studies?', 'They reduce the effect of chance and individual variation, making results more reliable and representative.', 27),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'How can lifestyle affect mental health?', 'Exercise, sleep, diet and social contact improve mental health; drug and alcohol misuse and isolation worsen it.', 28),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'How can physical and mental health interact?', 'Long-term physical illness increases risk of depression; depression can slow recovery and reduce healthy behaviours.', 29),
  ('Biology', 'OCR B', 'gcse', 'B2.5', 'Lifestyle, genes and the environment', 'How can a person''s environment be a risk factor?', 'e.g. air pollution (asthma, lung cancer), radon gas, occupational asbestos, or poverty limiting access to healthy food and healthcare.', 30),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'Give three lifestyle changes recommended to treat CVD.', 'Stop smoking, eat a healthy diet low in saturated fat and salt, exercise regularly and lose weight.', 1),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'How do statins reduce CVD risk?', 'They reduce the amount of LDL cholesterol made by the liver, slowing fatty plaque build-up.', 2),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'Give one disadvantage of statins.', 'Side-effects such as muscle aches or liver problems, and they must be taken long-term; effect is not immediate.', 3),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'How does aspirin help people at risk of heart attack?', 'It reduces blood clotting, lowering the chance of a clot blocking an artery; risk is bleeding.', 4),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'How do drugs that lower blood pressure help treat CVD?', 'Lower pressure reduces damage to artery walls and reduces plaque formation and strain on the heart.', 5),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'What is a stent?', 'A mesh tube inserted into a narrowed coronary artery to hold it open and restore blood flow.', 6),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'Give one advantage and one disadvantage of stents.', 'Advantage: quick, minimally invasive, fast recovery. Disadvantage: risk of blood clots and the artery can narrow again.', 7),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'What is a coronary bypass operation?', 'A healthy blood vessel from elsewhere is grafted to carry blood around a blocked coronary artery.', 8),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'Why is a heart transplant a last resort?', 'Major surgery with risks, shortage of donors, and lifelong immunosuppressant drugs are needed to stop rejection.', 9),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'What does an artificial pacemaker do?', 'An electrical device that controls an irregular heartbeat by stimulating the heart to beat at the correct rate.', 10),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'How can faulty heart valves be treated?', 'Replaced with mechanical valves (long-lasting but need anti-clotting drugs) or biological valves from animals or donors.', 11),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'Why are immunosuppressant drugs needed after a transplant?', 'To stop the recipient''s immune system attacking and rejecting the donor organ''s foreign antigens.', 12),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'Give a disadvantage of immunosuppressant drugs.', 'They weaken the immune system, so the patient is more likely to get infections.', 13),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'Why is tissue typing done before a transplant?', 'A closer match between donor and recipient antigens reduces the chance of rejection.', 14),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'What is the difference between opt-in and opt-out organ donation?', 'Opt-in: people must register to donate. Opt-out: everyone is assumed a donor unless they register not to.', 15),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'How does surgery treat cancer?', 'The tumour and some surrounding tissue are removed; it may not remove cancer that has spread.', 16),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'How does radiotherapy treat cancer?', 'Targeted ionising radiation kills rapidly dividing cancer cells in one area; it may damage nearby healthy tissue.', 17),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'How does chemotherapy treat cancer?', 'Drugs kill or stop division of rapidly dividing cells throughout the body, including cells that have spread.', 18),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'Why does chemotherapy cause hair loss and low immunity?', 'It also affects healthy rapidly dividing cells such as hair follicles and bone marrow.', 19),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'Compare radiotherapy and chemotherapy.', 'Radiotherapy targets one area with radiation; chemotherapy uses drugs that reach the whole body, so treats spread cancer but has more widespread side-effects.', 20),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'How can monoclonal antibodies treat cancer?', 'They bind specifically to cancer cell antigens, delivering drugs or triggering the immune system, with less harm to healthy cells.', 21),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'What is the first treatment for type 2 diabetes?', 'Lifestyle change: losing weight, healthy diet and regular exercise to improve insulin sensitivity.', 22),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'How does metformin help treat type 2 diabetes?', 'It increases the body''s sensitivity to insulin and reduces glucose released by the liver.', 23),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'When is insulin used for type 2 diabetes?', 'When lifestyle change and other drugs do not control blood glucose well enough.', 24),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'What is the difference between public-health and personal-health interventions?', 'Public-health targets whole populations (e.g. sugar tax, smoking bans); personal-health targets individuals (e.g. prescriptions, diet plans).', 25),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'Give two examples of public-health measures for non-communicable disease.', 'Sugar tax, smoking ban in public places, health campaigns, food labelling and minimum alcohol pricing.', 26),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'What factors should be considered when evaluating a treatment?', 'Effectiveness, side-effects and risks, cost, availability, and ethical issues.', 27),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'Why might a doctor choose lifestyle change over drugs?', 'It has no drug side-effects, is cheap, and tackles the cause, though it relies on the patient''s commitment.', 28),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'What is personalised medicine?', 'Choosing drugs and doses based on a patient''s genome, so treatment is more effective with fewer side-effects.', 29),
  ('Biology', 'OCR B', 'gcse', 'B2.6', 'Treating non-communicable disease', 'What is a drug''s efficacy?', 'How well the drug produces the intended effect, i.e. how well it works in treating the condition.', 30),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'What is photosynthesis?', 'The process in which plants and algae use light energy to make glucose and oxygen from carbon dioxide and water.', 1),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'Give the word equation for photosynthesis.', 'Carbon dioxide + water → glucose + oxygen (using light energy absorbed by chlorophyll).', 2),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'Give the balanced symbol equation for photosynthesis.', '6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂.', 3),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'Where does photosynthesis take place?', 'In chloroplasts, mainly in palisade mesophyll cells of leaves.', 4),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'What is the role of chlorophyll?', 'A green pigment in chloroplasts that absorbs light energy for photosynthesis.', 5),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'Why is photosynthesis described as endothermic?', 'It takes in energy (light) from the surroundings; the energy is stored in glucose.', 6),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', '(Higher) What are the two main stages of photosynthesis?', '(Higher) Light energy splits water into oxygen and hydrogen; hydrogen then combines with carbon dioxide to make glucose.', 7),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'Why are producers important in food chains?', 'They make glucose by photosynthesis, providing biomass and energy for all other organisms.', 8),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'Give four uses of glucose made in photosynthesis.', 'Respiration, making starch for storage, cellulose for cell walls, lipids for seeds, and amino acids for proteins.', 9),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'Why do plants store glucose as starch?', 'Starch is insoluble, so it does not affect water movement by osmosis, and it is compact.', 10),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'What extra substance must glucose be combined with to make amino acids?', 'Nitrate ions absorbed from the soil.', 11),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'In what form is sugar transported around the plant?', 'As sucrose, dissolved in phloem sap.', 12),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'Describe how to test a leaf for starch.', 'Boil in water to kill cells, heat in ethanol (water bath) to remove chlorophyll, rinse, add iodine; blue-black shows starch.', 13),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'Why is ethanol heated in a water bath, not directly over a flame?', 'Ethanol is highly flammable.', 14),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'How do you show that light is needed for photosynthesis?', 'Destarch a plant in the dark, cover part of a leaf with foil, expose to light, then test for starch; only the uncovered part turns blue-black.', 15),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'How do variegated leaves show that chlorophyll is needed?', 'After light and a starch test, only green areas turn blue-black; white areas without chlorophyll make no starch.', 16),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'What is a limiting factor?', 'The factor in shortest supply that stops the rate of photosynthesis increasing further.', 17),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'Name three limiting factors of photosynthesis.', 'Light intensity, carbon dioxide concentration and temperature (also amount of chlorophyll).', 18),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'What does a rate graph that levels off show?', 'The factor on the x-axis is no longer limiting; another factor (e.g. CO₂ or temperature) is now limiting.', 19),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'Why does the rate of photosynthesis fall at high temperatures?', 'The enzymes controlling photosynthesis denature, so their active sites change shape.', 20),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'How is the rate of photosynthesis measured in pondweed (PAG 5)?', 'Count oxygen bubbles released per minute (or collect gas volume) with a lamp at different distances; keep temperature and CO₂ constant.', 21),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'Why is sodium hydrogen carbonate added in the pondweed experiment?', 'It provides a steady source of carbon dioxide so CO₂ is not limiting.', 22),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'How is temperature kept constant in the pondweed practical?', 'Place a beaker of water (heat shield) between the lamp and the tube, or use an LED, and monitor with a thermometer.', 23),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', '(Higher) State the inverse square law for light intensity.', '(Higher) Light intensity is proportional to 1 ÷ distance², so halving the distance from the lamp quadruples the light intensity.', 24),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', '(Higher) A lamp is moved from 20 cm to 10 cm. By what factor does light intensity change?', '(Higher) Distance halves, so intensity increases by 2² = 4 times.', 25),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'How do greenhouse growers increase yield?', 'Use artificial lighting, heaters and paraffin burners or CO₂ generators, so no factor limits; must balance cost against extra yield.', 26),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'How is a leaf adapted for photosynthesis?', 'Broad for large surface area, thin for short diffusion path, many chloroplasts in palisade cells, stomata for gas exchange, veins to carry water and sugar.', 27),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'What are enzymes?', 'Biological catalysts (proteins) that speed up reactions, such as those in photosynthesis, without being used up.', 28),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'Explain the lock-and-key model of enzyme action.', 'The substrate has a complementary shape to the enzyme''s active site, fits into it, and the reaction occurs; products are released.', 29),
  ('Biology', 'OCR B', 'gcse', 'B3.1', 'Photosynthesis', 'How does pH affect enzyme activity (PAG 4)?', 'Activity is highest at the optimum pH; at extremes the active site changes shape (denatures) so the substrate no longer fits.', 30),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'What substances do plants need to take in?', 'Carbon dioxide and water for photosynthesis, oxygen for respiration, and mineral ions such as nitrate, phosphate, potassium and magnesium.', 1),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'Why do plants need nitrate ions?', 'To make amino acids and therefore proteins for growth.', 2),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'What is a symptom of nitrate deficiency?', 'Stunted growth and yellowing of older leaves.', 3),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'Why do plants need magnesium ions?', 'To make chlorophyll; deficiency causes yellow leaves (chlorosis).', 4),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'Why do plants need phosphate ions?', 'To make DNA and cell membranes, and for respiration; deficiency causes poor root growth and purple discoloured leaves.', 5),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'Why do plants need potassium ions?', 'To help enzymes involved in photosynthesis and respiration; deficiency causes yellow leaves with dead patches.', 6),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'What is diffusion?', 'The net movement of particles from an area of higher concentration to lower concentration; it is passive.', 7),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'What is osmosis?', 'The net movement of water molecules from a dilute solution to a more concentrated solution through a partially permeable membrane.', 8),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'What is active transport?', 'Movement of substances from a lower to a higher concentration, against the concentration gradient, using energy from respiration.', 9),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'How do root hair cells take up water?', 'By osmosis: soil water is more dilute than cell sap, so water moves in across the partially permeable membrane.', 10),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'How do root hair cells take up mineral ions?', 'By active transport, because ions are usually more concentrated inside the cell than in the soil.', 11),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'Give three adaptations of root hair cells.', 'Long projection giving large surface area, thin wall for short pathway, and many mitochondria to release energy for active transport.', 12),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'Why might waterlogged soil reduce mineral uptake?', 'Lack of oxygen reduces aerobic respiration in roots, so less energy for active transport.', 13),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'How does carbon dioxide enter a leaf?', 'By diffusion through open stomata into air spaces, then into mesophyll cells down a concentration gradient.', 14),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'What do guard cells do?', 'Control the opening and closing of stomata, balancing gas exchange with water loss.', 15),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', '(Higher) How do guard cells open a stoma?', '(Higher) Water enters guard cells by osmosis; they become turgid and, with thicker inner walls, bend apart to open the pore.', 16),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'What does xylem transport?', 'Water and mineral ions from the roots up to the leaves, in one direction only.', 17),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'Describe the structure of xylem.', 'Dead cells joined end-to-end forming hollow tubes with no end walls, strengthened with lignin.', 18),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'What does phloem transport?', 'Dissolved sugars (sucrose) from leaves to other parts of the plant, in both directions; this is translocation.', 19),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'Describe the structure of phloem.', 'Living sieve tube cells with perforated end walls (sieve plates), supported by companion cells.', 20),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'What is transpiration?', 'The loss of water vapour from the leaves, mainly by evaporation and diffusion through the stomata.', 21),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'What is the transpiration stream?', 'The continuous movement of water from roots, up the xylem and out of the leaves, driven by evaporation.', 22),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'How does light intensity affect transpiration rate?', 'Brighter light opens more stomata, so the rate increases.', 23),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'How does temperature affect transpiration rate?', 'Higher temperature increases evaporation and diffusion, so the rate increases.', 24),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'How does wind affect transpiration rate?', 'Wind removes water vapour from around the leaf, keeping a steep concentration gradient, so the rate increases.', 25),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'How does humidity affect transpiration rate?', 'High humidity reduces the concentration gradient of water vapour, so the rate decreases.', 26),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'What does a potometer measure?', 'The rate of water uptake by a cut shoot, which is used to estimate the rate of transpiration.', 27),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'A potometer bubble moves 30 mm in 5 minutes. Calculate the rate of water uptake.', 'Rate = distance ÷ time = 30 ÷ 5 = 6 mm per minute.', 28),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'Describe the potato osmosis practical (PAG 8).', 'Weigh equal potato cylinders, place in different sucrose concentrations for 30 min, blot and reweigh, calculate % change in mass and plot against concentration.', 29),
  ('Biology', 'OCR B', 'gcse', 'B3.2', 'Producer substances', 'A potato piece changes from 2.50 g to 2.20 g. Calculate the percentage change in mass.', '(2.20 − 2.50) ÷ 2.50 × 100 = −12%; water left by osmosis because the solution was more concentrated.', 30),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'What is a population?', 'All the organisms of one species living in a habitat.', 1),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'What is a community?', 'All the populations of different species living and interacting in a habitat.', 2),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'What is an ecosystem?', 'A community of organisms interacting with each other and with the non-living (abiotic) parts of their environment.', 3),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'What is meant by interdependence?', 'Organisms in a community depend on each other for food, shelter, pollination, seed dispersal and so on; a change in one population affects others.', 4),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'What do the arrows in a food chain show?', 'The direction of energy and biomass transfer, from the organism eaten to the one that eats it.', 5),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'What is a producer?', 'An organism that makes its own food by photosynthesis, e.g. plants and algae; the first trophic level.', 6),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'What is a primary consumer?', 'A herbivore that eats producers; the second trophic level.', 7),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'What is a trophic level?', 'The position of an organism in a food chain, e.g. producer (level 1), primary consumer (level 2).', 8),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'What is an apex predator?', 'A carnivore at the top of a food chain with no natural predators.', 9),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'What is a food web?', 'A diagram of many interlinked food chains in an ecosystem.', 10),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'In a food web, why might removing one species affect many others?', 'Its predators lose food and decline, its prey may increase, and competitors may be affected, because organisms are interdependent.', 11),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'Why is only around 10% of biomass transferred between trophic levels?', 'Much is lost as heat from respiration, in waste (faeces, urine) and as uneaten or indigestible parts.', 12),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'Why do food chains rarely have more than four or five trophic levels?', 'So much energy and biomass is lost at each level that too little remains to support more levels.', 13),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'Calculate the efficiency of transfer if grass has 2000 kg biomass and rabbits 150 kg.', 'Efficiency = 150 ÷ 2000 × 100 = 7.5%.', 14),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'What does a pyramid of biomass show?', 'The total dry mass of living material at each trophic level; it is almost always pyramid-shaped.', 15),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'Why can a pyramid of numbers be an irregular shape?', 'One large producer (e.g. an oak tree) can feed many small consumers, so the base bar is narrow.', 16),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'What do decomposers do?', 'Bacteria and fungi break down dead organisms and waste, respiring and returning CO₂ and mineral ions to the environment.', 17),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'What conditions speed up decay?', 'Warm temperature, moisture, plenty of oxygen and lots of microorganisms.', 18),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'Why do decomposers matter for plants?', 'They recycle mineral ions such as nitrates back into the soil so plants can absorb them again.', 19),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'How is carbon removed from the atmosphere?', 'By photosynthesis in plants and algae, converting CO₂ into glucose and biomass.', 20),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'How is carbon returned to the atmosphere?', 'By respiration of plants, animals and decomposers, and by combustion of fuels.', 21),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'How does carbon move through a food chain?', 'As carbon compounds in biomass when organisms are eaten.', 22),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'Outline the water cycle.', 'Water evaporates and is transpired, condenses into clouds, falls as precipitation, then runs off or soaks into soil and returns to seas.', 23),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'Why do plants and animals need nitrogen?', 'To make proteins (and DNA); plants absorb it as nitrate ions, animals get it by eating.', 24),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'What do nitrogen-fixing bacteria do?', 'Convert nitrogen gas from the air into ammonia or nitrates; some live in root nodules of legumes such as peas and clover.', 25),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'What do nitrifying bacteria do?', 'Convert ammonium compounds into nitrites and then nitrates that plants can absorb.', 26),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'What do denitrifying bacteria do?', 'Convert nitrates in soil back into nitrogen gas, especially in waterlogged soil.', 27),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'What is mutualism? Give an example.', 'A relationship where both species benefit, e.g. nitrogen-fixing bacteria in legume nodules, or bees pollinating flowers.', 28),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'What is parasitism? Give an example.', 'The parasite benefits and lives on or in the host, which is harmed, e.g. a tapeworm in the gut.', 29),
  ('Biology', 'OCR B', 'gcse', 'B3.3', 'Interdependence', 'Describe the predator–prey cycle.', 'Prey increase, so predators increase; more predators eat more prey so prey fall; then predators fall from lack of food; predator peaks lag behind prey.', 30),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'What are abiotic factors? Give three examples.', 'Non-living factors affecting a community, e.g. light intensity, temperature, water, soil pH, mineral ions, wind and CO₂ or O₂ levels.', 1),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'What are biotic factors? Give three examples.', 'Living factors affecting a community, e.g. food availability, predators, pathogens and competition.', 2),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'What do plants compete for?', 'Light, space, water and mineral ions from the soil.', 3),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'What do animals compete for?', 'Food, territory, water and mates.', 4),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'How could a new pathogen affect a population?', 'More individuals become ill and die, so the population falls; populations that eat it or compete with it are also affected.', 5),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'What is a quadrat used for?', 'A square frame used to sample the number or percentage cover of slow-moving or stationary organisms in a set area.', 6),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'Why should quadrats be placed randomly?', 'To avoid bias so the sample is representative; use random coordinates from a number generator.', 7),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'How do you estimate a population using quadrats?', 'Population = mean number per quadrat × (total area ÷ quadrat area).', 8),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'A 0.25 m² quadrat has a mean of 6 daisies. Estimate the number in a 400 m² field.', '400 ÷ 0.25 = 1600 quadrats; 6 × 1600 = 9600 daisies.', 9),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'Why does using more quadrats improve the estimate?', 'It gives a more representative mean and reduces the effect of anomalous results.', 10),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'What is a transect used for?', 'To study how the distribution of organisms changes across an area or along an environmental gradient.', 11),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'Describe how to carry out a belt transect (PAG 3).', 'Lay a tape across the area; place quadrats at regular intervals; count organisms and measure abiotic factors (e.g. light) at each point; repeat transects.', 12),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'What is the capture–mark–recapture method used for?', 'Estimating the population size of mobile animals such as woodlice or snails.', 13),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'State the formula for capture–mark–recapture.', 'Population = (number in first sample × number in second sample) ÷ number marked in second sample.', 14),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', '20 snails are marked and released. Later 30 are caught, 5 marked. Estimate the population.', '(20 × 30) ÷ 5 = 120 snails.', 15),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'Give two assumptions of capture–mark–recapture.', 'Marks do not harm or affect survival, marked animals mix fully, and no births, deaths or migration between samples.', 16),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'What is biodiversity?', 'The variety of all the different species of organisms in an area, or on Earth.', 17),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'Why is high biodiversity important?', 'It makes an ecosystem more stable, as species depend on each other for food, shelter and maintaining the physical environment.', 18),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'How does deforestation affect ecosystems?', 'Destroys habitats, reduces biodiversity, and less CO₂ is absorbed by photosynthesis; burning releases CO₂.', 19),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'Explain eutrophication.', 'Fertiliser runs into water; algae grow rapidly and block light; plants die; bacteria decomposing them respire and use up oxygen; fish and other animals die.', 20),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'How does sulfur dioxide pollution affect ecosystems?', 'Forms acid rain, which damages trees, leaches minerals from soil and lowers the pH of lakes, killing organisms.', 21),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'How does overfishing affect populations?', 'Fish are removed faster than they reproduce, so populations crash, which can cause extinction and disrupt food webs.', 22),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'What is an indicator species?', 'A species whose presence, absence or abundance shows the level of pollution in an environment.', 23),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'What do lichens indicate?', 'Clean air: many lichen species are sensitive to sulfur dioxide, so lots of lichens show low air pollution.', 24),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'Which invertebrates indicate clean or polluted water?', 'Mayfly nymphs and freshwater shrimps show clean, well-oxygenated water; bloodworms and sludge worms show polluted, low-oxygen water.', 25),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'How do populations respond to a change in an abiotic factor?', 'Species better adapted to the new conditions increase while others decline, migrate or die out, changing the community.', 26),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'Give three ways of conserving species and habitats.', 'Protected nature reserves, captive breeding programmes, seed banks, fishing quotas and habitat restoration.', 27),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'What is a seed bank?', 'A store of seeds from many plant species, preserving genetic variety in case wild populations are lost.', 28),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'Why might conservation schemes cause conflict?', 'They can limit land use, farming, fishing or development, affecting local people''s income.', 29),
  ('Biology', 'OCR B', 'gcse', 'B3.4', 'Populations', 'Why is the human population growth a threat to ecosystems?', 'More people use more land, resources and energy and produce more waste and pollution, reducing habitats and biodiversity.', 30),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'What is cellular respiration?', 'A series of enzyme-controlled chemical reactions in every living cell that releases energy from glucose for cell processes.', 1),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'Is respiration endothermic or exothermic?', 'Exothermic: it transfers energy to the surroundings (some as heat).', 2),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'Give the word equation for aerobic respiration.', 'glucose + oxygen → carbon dioxide + water (energy released).', 3),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'Give the balanced symbol equation for aerobic respiration.', 'C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O', 4),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'Where in the cell does aerobic respiration mainly take place?', 'In the mitochondria (the first stage, glycolysis, occurs in the cytoplasm).', 5),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'Where does anaerobic respiration take place?', 'In the cytoplasm.', 6),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'Give the word equation for anaerobic respiration in animal cells.', 'glucose → lactic acid (small amount of energy released).', 7),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'Give the word equation for anaerobic respiration in plant cells and yeast.', 'glucose → ethanol + carbon dioxide (small amount of energy released). In yeast this is called fermentation.', 8),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'Why does anaerobic respiration release less energy than aerobic respiration?', 'Glucose is only partially broken down (incompletely oxidised), so much energy stays locked in lactic acid or ethanol.', 9),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'What molecule is made in respiration to transfer energy within cells?', 'ATP (adenosine triphosphate), which releases energy when it is broken down to drive cell processes.', 10),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'Give four uses of energy from respiration in living organisms.', 'Muscle contraction (movement), active transport, synthesis of large molecules (e.g. proteins), maintaining body temperature in birds and mammals.', 11),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'When do human muscle cells respire anaerobically?', 'During vigorous exercise when oxygen cannot be supplied fast enough for aerobic respiration to meet energy demand.', 12),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'Why can lactic acid build-up cause muscle fatigue?', 'Lactic acid accumulates in muscles, contributing to fatigue and cramp, so muscles contract less efficiently.', 13),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'What is oxygen debt?', '(Higher) The extra oxygen needed after exercise to break down the lactic acid that built up during anaerobic respiration.', 14),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'Why do you keep breathing deeply after exercise stops?', 'To repay the oxygen debt: extra oxygen is taken to the liver to oxidise lactic acid to carbon dioxide and water.', 15),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'How does heart rate change during exercise and why?', 'It increases to pump more blood carrying oxygen and glucose to muscles and to remove carbon dioxide faster.', 16),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'Compare the oxygen requirement and products of aerobic and anaerobic respiration in animals.', 'Aerobic needs oxygen and produces CO₂ and water; anaerobic needs no oxygen and produces lactic acid only.', 17),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'Which type of respiration releases the most energy per glucose molecule?', 'Aerobic respiration, because glucose is completely broken down.', 18),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'How is anaerobic respiration in yeast used in bread making?', 'Carbon dioxide produced by fermentation makes the dough rise; the ethanol evaporates during baking.', 19),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'How is anaerobic respiration in yeast used in brewing?', 'Yeast ferments sugars to produce ethanol (alcohol) for beer and wine; CO₂ can give fizz.', 20),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'What is biogas and how is it produced?', 'Mainly methane, produced when microorganisms respire anaerobically to break down organic waste in a digester. It is used as a fuel.', 21),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'Which organisms respire anaerobically in waterlogged soils, deep wounds and sewage?', 'Some bacteria and plant root cells, as oxygen is in short supply in these places.', 22),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'What is metabolism?', 'The sum of all the chemical reactions in a cell or organism.', 23),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'Give two examples of metabolic reactions that use energy from respiration.', 'Building proteins from amino acids; joining glucose into starch, glycogen or cellulose; making lipids from fatty acids and glycerol.', 24),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'Why does respiration need enzymes?', 'Each step is catalysed by specific enzymes, so the rate depends on temperature and pH affecting enzyme activity.', 25),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'How can you measure the rate of respiration in yeast?', 'Measure the volume of CO₂ released per minute, e.g. count bubbles or collect gas in a syringe or upturned measuring cylinder.', 26),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'Practical: How does temperature affect the rate of yeast respiration?', 'Rate increases up to an optimum (around 35–40 °C) as enzymes and particles move faster; above it enzymes denature and rate falls.', 27),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'How can a respirometer be used to measure respiration in small organisms?', 'Soda lime absorbs CO₂, so oxygen uptake causes a coloured liquid to move along a capillary tube; distance moved per minute shows rate.', 28),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'In a respiration experiment, why is a control with glass beads used?', 'To show any change is due to the living organisms and not to temperature or pressure changes.', 29),
  ('Biology', 'OCR B', 'gcse', 'B4.1', 'Cellular respiration', 'Calculate the rate of CO₂ production if 24 cm³ of gas is collected in 8 minutes.', 'Rate = volume ÷ time = 24 ÷ 8 = 3 cm³/min.', 30),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'What is the function of the mitochondria?', 'Site of aerobic respiration, releasing energy for the cell.', 1),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'What is the function of the nucleus?', 'Contains genetic material (DNA in chromosomes) that controls the activities of the cell.', 2),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'What is the function of the cell membrane?', 'A partially permeable barrier that controls which substances enter and leave the cell.', 3),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'What is the function of the cytoplasm?', 'Gel-like fluid where many chemical reactions take place, controlled by enzymes.', 4),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'What is the function of ribosomes?', 'Site of protein synthesis, where amino acids are joined in the order coded by mRNA.', 5),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'Name three structures found in plant cells but not animal cells.', 'Cellulose cell wall, chloroplasts and a permanent vacuole containing cell sap.', 6),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'What is the function of the cellulose cell wall?', 'Strengthens and supports the cell and stops it bursting when it takes in water.', 7),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'What is the difference between eukaryotic and prokaryotic cells?', 'Eukaryotic cells have a nucleus and membrane-bound organelles; prokaryotic cells (bacteria) have no nucleus, with DNA free in the cytoplasm.', 8),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'Describe the genetic material in a bacterial cell.', 'A single circular loop of chromosomal DNA free in the cytoplasm, plus small rings of DNA called plasmids.', 9),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'Name four structures found in a bacterial cell.', 'Cell wall, cell membrane, cytoplasm, ribosomes, circular DNA and plasmids (some also have a flagellum).', 10),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'How do the sizes of prokaryotic and eukaryotic cells compare?', 'Prokaryotic cells are much smaller (about 0.1–5 μm) than eukaryotic cells (about 10–100 μm).', 11),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'How is the inner membrane of a mitochondrion adapted for its function?', 'It is highly folded (cristae), giving a large surface area for respiration enzymes.', 12),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'Why do muscle and sperm cells contain many mitochondria?', 'They need a lot of energy from aerobic respiration for contraction and swimming.', 13),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'Why do root hair cells contain many mitochondria?', 'They need energy from respiration for active transport of mineral ions from the soil.', 14),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'Give the equation for magnification.', 'Magnification = size of image ÷ real size of object.', 15),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'Calculate the magnification if image size is 12 mm and real size is 0.04 mm.', 'Magnification = image ÷ real = 12 ÷ 0.04 = ×300.', 16),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'A mitochondrion image is 30 mm long and the real length is 3 μm. Calculate the magnification.', 'Convert: 30 mm = 30 000 μm. Magnification = 30 000 ÷ 3 = ×10 000.', 17),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'How many micrometres are in one millimetre?', '1000 μm = 1 mm (and 1000 nm = 1 μm).', 18),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'What is resolution?', 'The smallest distance between two points that can still be seen as separate; it determines how much detail is visible.', 19),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'Why can electron microscopes see more detail than light microscopes?', 'Electrons have a much shorter wavelength than light, giving much higher resolution and magnification.', 20),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'Compare the maximum magnification and resolution of light and electron microscopes.', 'Light: about ×1500, resolution about 200 nm. Electron: up to about ×2 000 000, resolution about 0.2 nm.', 21),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'Give one disadvantage of the electron microscope.', 'Specimens must be dead (in a vacuum); microscopes are large, expensive and need specialist training.', 22),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'How did the electron microscope change our understanding of cells?', 'It revealed sub-cellular structures such as the internal structure of mitochondria, ribosomes and membranes in detail.', 23),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'What is a scanning electron microscope used for?', 'Producing 3D images of the surface of specimens (transmission EMs give 2D images of internal structure).', 24),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'Practical: Describe how to prepare a slide of onion epidermis cells.', 'Peel a thin layer of epidermis, place on slide in a drop of water, add iodine stain, lower a coverslip at an angle to avoid air bubbles.', 25),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'Practical: Why is a stain used when viewing cells under a light microscope?', 'To add contrast so structures (e.g. nucleus) are visible; e.g. iodine for plant cells, methylene blue for cheek cells.', 26),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'Practical: How should you focus a light microscope?', 'Start with the lowest-power objective, use the coarse focus to bring the stage up, then fine focus; switch to higher power and refocus.', 27),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'Practical: How do you estimate cell size using a microscope?', 'Measure field of view diameter (e.g. with a ruler or graticule), count cells across it, then divide the diameter by the number of cells.', 28),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'How is a sperm cell adapted to its function?', 'Tail for swimming, many mitochondria for energy, acrosome containing enzymes to digest the egg membrane, haploid nucleus.', 29),
  ('Biology', 'OCR B', 'gcse', 'B4.2', 'Cell structures and mitochondria', 'How is a red blood cell adapted to carry oxygen?', 'Biconcave shape for large surface area, no nucleus so more room for haemoglobin, flexible to squeeze through capillaries.', 30),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'What is mitosis?', 'Cell division producing two genetically identical diploid daughter cells.', 1),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'What are the three main uses of mitosis?', 'Growth, repair of damaged tissue and asexual reproduction.', 2),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'What happens during interphase of the cell cycle?', 'The cell grows, organelles such as mitochondria and ribosomes are copied, and DNA replicates so each chromosome forms two chromatids.', 3),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'Outline the main stages of mitosis.', 'Chromosomes condense, line up across the middle of the cell, chromatids are pulled to opposite poles by spindle fibres, two new nuclei form, then cytoplasm divides.', 4),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'What is cytokinesis?', 'Division of the cytoplasm and cell membrane to form two separate daughter cells.', 5),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'Why must DNA be replicated before mitosis?', 'So each daughter cell receives a full, identical copy of all the genetic information.', 6),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'How many chromosomes are in a human body cell after mitosis?', '46 (23 pairs) – the same as the parent cell.', 7),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'What is a zygote and how does it develop into an embryo?', 'A fertilised egg; it divides repeatedly by mitosis to form a ball of cells (embryo), which later differentiate.', 8),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'What is differentiation?', 'The process by which a cell becomes specialised for a particular function, by switching some genes on and others off.', 9),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'What is a stem cell?', 'An unspecialised cell that can divide to produce more stem cells or differentiate into specialised cell types.', 10),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'What are embryonic stem cells?', 'Unspecialised cells from early embryos (up to about the 8–16 cell stage or blastocyst) that can differentiate into any type of cell.', 11),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'How do adult stem cells differ from embryonic stem cells?', 'Adult stem cells (e.g. bone marrow) can only differentiate into a limited range of cell types; embryonic stem cells can form any type.', 12),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'What are meristems?', 'Regions of unspecialised plant cells at root and shoot tips (and in stems) that divide by mitosis and can differentiate into any plant cell type.', 13),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'Why can plants regrow lost parts more easily than animals?', 'Plant meristem cells keep the ability to differentiate throughout life; most animal cells lose it early in development.', 14),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'How do plants grow?', 'Cell division in meristems, followed by cell elongation (enlargement) and differentiation.', 15),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'How are plant meristems used to make clones?', 'Small pieces of meristem tissue are grown on sterile nutrient medium with hormones (tissue culture) to produce many identical plants.', 16),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'Give two potential medical uses of stem cells.', 'Replacing damaged cells in conditions such as type 1 diabetes, paralysis, heart damage; bone marrow transplants for leukaemia; testing drugs.', 17),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'Give two ethical objections to using embryonic stem cells.', 'Embryos are destroyed, which some believe is ending a potential life; religious objections; concern about consent.', 18),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'Give two practical risks of stem cell therapy.', 'Cells may divide uncontrollably and form tumours; they may be rejected by the immune system; viral contamination.', 19),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'What is therapeutic cloning?', 'Creating an embryo with the patient''s own genes so its stem cells will not be rejected when transplanted.', 20),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'What are iPS cells?', 'Induced pluripotent stem cells: adult cells reprogrammed to behave like embryonic stem cells, avoiding the need to destroy embryos.', 21),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'What is the difference between growth in plants and animals?', 'Animals grow mainly in early life and stop at maturity; plants grow throughout their life at meristems.', 22),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'Why is dry mass the most reliable measure of growth?', 'It removes variation caused by changing water content; but the organism must be killed to measure it.', 23),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'Give one advantage and one disadvantage of using length or height to measure growth.', 'Advantage: quick, simple and non-destructive. Disadvantage: ignores growth in width or mass.', 24),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'What is a percentile growth chart used for?', 'Comparing a baby''s mass, length or head circumference with the population to check growth is normal over time.', 25),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'A baby is on the 25th percentile for mass. What does this mean?', '25% of babies of the same age have a lower mass and 75% have a higher mass.', 26),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'Why might a doctor be concerned about a baby''s growth chart?', 'If measurements cross percentile lines, or are very high or low, it may indicate malnutrition, disease or a genetic condition.', 27),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'What is cancer in terms of the cell cycle?', 'Uncontrolled cell division due to mutations in genes controlling the cell cycle, forming a tumour.', 28),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'Practical: How can you observe mitosis in a root tip?', 'Cut a root tip, treat with acid to separate cells, stain (e.g. toluidine blue), squash under a coverslip and view at high power.', 29),
  ('Biology', 'OCR B', 'gcse', 'B4.3', 'Growth and development', 'Calculate the mitotic index if 24 of 300 cells are in mitosis.', 'Mitotic index = cells in mitosis ÷ total cells = 24 ÷ 300 = 0.08 (8%).', 30),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'What is diffusion?', 'The net movement of particles from a region of higher concentration to lower concentration, down a concentration gradient. It is passive.', 1),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'What is osmosis?', 'The net movement of water molecules across a partially permeable membrane from a dilute solution (high water concentration) to a more concentrated solution.', 2),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'What is active transport?', 'Movement of substances against a concentration gradient, from low to high concentration, using energy from respiration and carrier proteins.', 3),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'Give two factors that increase the rate of diffusion.', 'A larger concentration gradient, a larger surface area, a shorter diffusion distance, a higher temperature.', 4),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'Why do large organisms need exchange surfaces and transport systems?', 'Their surface area to volume ratio is small, so diffusion across the body surface is too slow to supply all cells.', 5),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'Calculate the surface area to volume ratio of a 2 cm cube.', 'SA = 6 × 2 × 2 = 24 cm²; volume = 8 cm³; ratio = 24 : 8 = 3 : 1.', 6),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'How are alveoli adapted for gas exchange?', 'Huge surface area, walls one cell thick for short diffusion distance, moist lining, rich capillary network maintaining a steep gradient.', 7),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'How is a steep concentration gradient maintained in the lungs?', 'Ventilation brings in fresh air and blood flow constantly removes oxygen and brings carbon dioxide.', 8),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'How are villi in the small intestine adapted for absorption?', 'Large surface area (microvilli), thin walls one cell thick, good blood supply, and cells with many mitochondria for active transport.', 9),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'What is meant by a double circulatory system?', 'Blood passes through the heart twice per complete circuit: heart to lungs and back, then heart to body and back.', 10),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'Why is a double circulation an advantage?', 'Blood returning from the lungs is re-pressurised, so oxygenated blood reaches body tissues quickly at high pressure.', 11),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'Why is the left ventricle wall thicker than the right?', 'It pumps blood at high pressure all round the body; the right ventricle only pumps to the nearby lungs.', 12),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'What is the function of the heart valves?', 'To prevent backflow of blood, ensuring it flows in one direction through the heart.', 13),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'Trace the path of blood through the heart from the vena cava.', 'Vena cava → right atrium → right ventricle → pulmonary artery → lungs → pulmonary vein → left atrium → left ventricle → aorta.', 14),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'How are arteries adapted to their function?', 'Thick muscular and elastic walls to withstand and maintain high pressure; narrow lumen.', 15),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'How are capillaries adapted for exchange?', 'Walls one cell thick for short diffusion distance; very narrow and numerous giving a large surface area close to cells.', 16),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'How are veins adapted to their function?', 'Wide lumen, thin walls and valves to prevent backflow of low-pressure blood returning to the heart.', 17),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'What is the function of plasma?', 'Liquid that carries dissolved substances: glucose, amino acids, CO₂, urea, hormones, and also blood cells and heat.', 18),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'How does haemoglobin carry oxygen?', '(Higher) Haemoglobin binds oxygen in the lungs forming oxyhaemoglobin, and releases it in tissues where oxygen concentration is low.', 19),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'What is the function of platelets?', 'Cell fragments that help blood clot at wounds, preventing blood loss and entry of pathogens.', 20),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'What is the function of xylem?', 'Transports water and mineral ions from roots to leaves; made of dead hollow cells strengthened with lignin.', 21),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'What is the function of phloem?', 'Transports dissolved sugars (sucrose) from leaves to the rest of the plant in both directions (translocation); living cells with sieve plates.', 22),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'What is transpiration?', 'Loss of water vapour from leaves by evaporation and diffusion through stomata, which pulls water up the xylem.', 23),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'How do guard cells control water loss?', 'Guard cells change shape to open or close stomata; stomata close when water is scarce, reducing transpiration.', 24),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'Give four factors that increase the rate of transpiration.', 'Higher temperature, higher light intensity, lower humidity, increased air movement (wind).', 25),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'How do root hair cells absorb water and minerals?', 'Large surface area; water enters by osmosis and mineral ions by active transport from dilute soil water.', 26),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'Practical: How is a potometer used?', 'It measures water uptake by a cut shoot: the distance an air bubble moves along a capillary tube in a set time estimates transpiration rate.', 27),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'Practical: Describe how to investigate osmosis using potato cylinders.', 'Weigh cylinders, place in a range of sucrose concentrations, leave, blot dry and reweigh; calculate percentage change in mass.', 28),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'Practical: A potato cylinder changes from 2.50 g to 2.20 g. Calculate the percentage change in mass.', '(2.20 − 2.50) ÷ 2.50 × 100 = −12%.', 29),
  ('Biology', 'OCR B', 'gcse', 'B5.1', 'Substances in, out and around the body', 'Practical: How do you find the concentration of potato cell sap from osmosis results?', 'Plot percentage change in mass against concentration; where the line crosses zero change, the solution matches cell contents.', 30),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'What is a stimulus?', 'A change in the internal or external environment that can be detected by receptors.', 1),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'What is the general pathway from stimulus to response?', 'Stimulus → receptor → coordinator (CNS) → effector → response.', 2),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'What are effectors?', 'Muscles that contract or glands that secrete hormones, bringing about a response.', 3),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'What makes up the central nervous system (CNS)?', 'The brain and spinal cord.', 4),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'What is the peripheral nervous system?', 'Sensory and motor neurones that connect receptors and effectors to the central nervous system.', 5),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'What does a sensory neurone do?', 'Carries electrical impulses from receptors to the CNS.', 6),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'What does a motor neurone do?', 'Carries electrical impulses from the CNS to effectors.', 7),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'What is the role of a relay neurone?', 'Found in the CNS; passes impulses from sensory neurones to motor neurones.', 8),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'What is the function of the myelin sheath?', 'Insulates the axon and speeds up the transmission of nerve impulses.', 9),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'How are neurones adapted to carry impulses?', 'Long axon to carry impulses over long distances, branched dendrites to connect with many neurones, myelin sheath for faster transmission.', 10),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'What is a synapse?', 'The tiny gap between two neurones, across which the signal is transmitted by chemicals.', 11),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'Describe how a signal crosses a synapse.', 'Impulse arrives, vesicles release neurotransmitter into the gap, it diffuses across and binds to receptors on the next neurone, triggering a new impulse.', 12),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'Why do synapses ensure impulses travel in one direction?', 'Neurotransmitter is only released from one side and the receptors are only on the other side.', 13),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'How can drugs affect synapses?', '(Higher) They may block receptors, mimic neurotransmitters, increase their release or stop their removal, changing impulse transmission.', 14),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'What is a reflex action?', 'A fast, automatic, involuntary response to a stimulus that does not involve the conscious part of the brain; protects the body from harm.', 15),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'Describe the reflex arc pathway.', 'Stimulus → receptor → sensory neurone → relay neurone (spinal cord) → motor neurone → effector → response.', 16),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'Why are reflexes faster than voluntary responses?', 'The impulse does not go to the conscious brain for processing, and only a few synapses are involved.', 17),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'Give two examples of human reflexes.', 'Withdrawing hand from a hot object, blinking, the knee jerk, pupil reflex in bright light.', 18),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'What is the function of the cerebral cortex?', 'Conscious thought, intelligence, memory, language and voluntary actions.', 19),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'What is the function of the cerebellum?', 'Coordinates muscle activity, balance and posture.', 20),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'What is the function of the medulla?', 'Controls unconscious activities such as heart rate and breathing rate.', 21),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'Give three methods used to study brain function.', 'Studying patients with brain damage, electrically stimulating parts of the brain, and MRI or fMRI scans showing active regions.', 22),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'Why is it difficult to treat damage to the brain and spinal cord?', 'Neurones do not easily repair; the brain is complex and delicate, and treatment risks damaging other areas; drugs struggle to reach it.', 23),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'What is the function of the retina?', 'Contains light-sensitive receptor cells (rods and cones) that convert light into nerve impulses.', 24),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'What are the functions of the cornea and lens?', 'Both refract light to focus it on the retina; the lens changes shape to adjust focus.', 25),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'What is the function of the iris?', 'Controls the size of the pupil and so the amount of light entering the eye.', 26),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'Describe how the eye focuses on a near object.', '(Higher) Ciliary muscles contract, suspensory ligaments slacken, lens becomes thicker and more convex, refracting light more strongly.', 27),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'What causes short-sightedness and how is it corrected?', 'Light focuses in front of the retina (eyeball too long or lens too strong); corrected with concave (diverging) lenses.', 28),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'What causes long-sightedness and how is it corrected?', 'Light focuses behind the retina (eyeball too short or lens too weak); corrected with convex (converging) lenses.', 29),
  ('Biology', 'OCR B', 'gcse', 'B5.2', 'The nervous system', 'Practical: How can reaction time be measured using a ruler drop test?', 'Drop a ruler between a person''s finger and thumb; record the distance caught, repeat and convert to time using a table or formula.', 30),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'What is a hormone?', 'A chemical messenger secreted by an endocrine gland directly into the bloodstream, which carries it to target organs.', 1),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'What is the endocrine system?', 'A system of glands that secrete hormones into the blood to control body processes.', 2),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'Why is the pituitary called the master gland?', 'It secretes hormones (e.g. FSH, LH, TSH, ADH) that control other glands in the body.', 3),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'Compare nervous and hormonal responses.', 'Nervous: electrical impulses, very fast, short-lived, precise. Hormonal: chemicals in blood, slower, longer-lasting, more widespread.', 4),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'Where is adrenaline produced and what is its role?', 'Adrenal glands; prepares the body for fight or flight in response to stress or danger.', 5),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'Give three effects of adrenaline on the body.', 'Increases heart rate and breathing rate, raises blood glucose by glycogen breakdown, diverts blood to muscles, dilates pupils.', 6),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'What does thyroxine do?', 'Produced by the thyroid gland; controls basal metabolic rate and is important for growth and development.', 7),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'How is thyroxine level controlled by negative feedback?', '(Higher) Low thyroxine causes the pituitary to release TSH, stimulating the thyroid; high thyroxine inhibits TSH release, so levels fall back.', 8),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'What is the role of insulin?', 'Released by the pancreas when blood glucose is high; causes cells to take in glucose and liver and muscle cells to store it as glycogen.', 9),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'What is the role of glucagon?', '(Higher) Released by the pancreas when blood glucose is low; causes the liver to convert glycogen back into glucose, released into the blood.', 10),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'What is the difference between glucose, glycogen and glucagon?', 'Glucose is the sugar in blood; glycogen is the stored carbohydrate in liver and muscles; glucagon is a hormone.', 11),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'What is the cause of type 1 diabetes?', 'The pancreas does not produce enough insulin, often because the immune system destroys insulin-producing cells; usually begins in childhood.', 12),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'What is the cause of type 2 diabetes?', 'Body cells no longer respond properly to insulin (insulin resistance); strongly linked to obesity and lack of exercise.', 13),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'How is type 1 diabetes treated?', 'Insulin injections, monitoring blood glucose and controlling carbohydrate intake.', 14),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'How is type 2 diabetes treated?', 'Controlled diet, exercise and weight loss; drugs such as metformin; insulin if needed.', 15),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'What is the role of FSH in the menstrual cycle?', 'Secreted by the pituitary; causes an egg to mature in the ovary and stimulates oestrogen production.', 16),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'What is the role of oestrogen in the menstrual cycle?', 'Secreted by the ovaries; causes the uterus lining to thicken, inhibits FSH and (Higher) stimulates LH release.', 17),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'What is the role of LH in the menstrual cycle?', 'Secreted by the pituitary; a surge of LH triggers ovulation, release of an egg around day 14.', 18),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'What is the role of progesterone in the menstrual cycle?', 'Maintains the thick uterus lining; inhibits FSH and LH. When it falls, menstruation begins.', 19),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'How does the combined contraceptive pill work?', 'Contains oestrogen and progesterone, which inhibit FSH and LH so no eggs mature or are released.', 20),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'Give two non-hormonal methods of contraception.', 'Condoms or diaphragms (barrier methods), copper IUD, spermicides, sterilisation, avoiding intercourse around ovulation.', 21),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'Give one advantage and one disadvantage of hormonal contraception.', 'Advantage: very effective if used correctly. Disadvantage: side effects such as mood changes or blood clots; no protection against STIs.', 22),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'How are hormones used to treat infertility?', '(Higher) FSH and LH are given in fertility drugs to stimulate eggs to mature and be released.', 23),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'Describe the main steps of IVF.', '(Higher) FSH/LH stimulate egg production; eggs collected and fertilised with sperm in a lab; embryos grown, then one or two inserted into the uterus.', 24),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'Give two drawbacks of IVF.', '(Higher) Low success rate, expensive, emotionally stressful, risk of multiple births, ethical issues over unused embryos.', 25),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'What is auxin?', 'A plant hormone that controls growth at shoot and root tips by promoting or inhibiting cell elongation.', 26),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'Explain phototropism in a shoot.', 'Auxin moves to the shaded side of the shoot, causing cells there to elongate faster, so the shoot bends towards the light.', 27),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'Explain gravitropism in a root.', 'Auxin collects on the lower side of the root, where it inhibits cell elongation, so the upper side grows faster and the root bends downwards.', 28),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'Give two commercial uses of plant hormones.', 'Auxins as weedkillers and rooting powders; ethene to ripen fruit; gibberellins to end seed dormancy, promote flowering and increase fruit size.', 29),
  ('Biology', 'OCR B', 'gcse', 'B5.3', 'Hormonal control', 'Practical: How would you investigate the effect of light on seedling growth?', 'Grow cress seedlings with light from one side versus all round or in darkness; measure shoot length and angle of bending; control water, temperature and species.', 30),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'What is homeostasis?', 'Maintaining a constant internal environment (e.g. temperature, water, blood glucose) for optimal cell and enzyme function.', 1),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'Why must internal conditions be kept constant?', 'Enzymes work best at optimum temperature and pH, and cells can be damaged by osmotic changes in water concentration.', 2),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'What is negative feedback?', 'A control mechanism in which a change from the set point triggers a response that reverses the change, returning conditions to normal.', 3),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'Name the components of a homeostatic control system.', 'Receptors detect change, a coordination centre processes information, and effectors produce a response.', 4),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'What is the normal human core body temperature?', 'About 37 °C.', 5),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'Which part of the brain monitors body temperature?', 'The thermoregulatory centre in the hypothalamus, which monitors blood temperature and receives impulses from skin receptors.', 6),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'How does sweating cool the body?', 'Sweat glands release sweat; water evaporates from the skin surface, transferring heat energy away from the body.', 7),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'What is vasodilation and when does it occur?', 'When the body is too hot: arterioles supplying skin capillaries widen, so more blood flows near the surface and more heat is lost by radiation.', 8),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'What is vasoconstriction and when does it occur?', 'When the body is too cold: arterioles supplying skin capillaries narrow, so less blood flows near the surface, reducing heat loss.', 9),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'How does shivering warm the body?', 'Rapid muscle contractions increase respiration, which releases heat energy.', 10),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'How do body hairs help when it is cold?', 'Erector muscles contract, raising hairs to trap a layer of insulating air (more effective in other mammals).', 11),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'Why should you not say blood vessels move nearer the skin?', 'Vessels do not move; they dilate or constrict, changing the volume of blood flowing near the surface.', 12),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'What is hypothermia?', 'When core body temperature falls dangerously low (below about 35 °C), slowing enzyme-controlled reactions.', 13),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'Why does water balance need to be controlled?', 'If body fluid concentration changes, cells gain or lose water by osmosis and may swell, burst or shrink, stopping them working properly.', 14),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'Give three ways water is lost from the body.', 'In urine, sweat and exhaled air (also faeces).', 15),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'What happens to animal cells in a solution more dilute than their cytoplasm?', 'Water enters by osmosis; with no cell wall they may swell and burst (lysis).', 16),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'What happens to plant cells placed in a concentrated solution?', 'Water leaves by osmosis; the cell becomes flaccid and the membrane may pull away from the wall (plasmolysis).', 17),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'What is the function of the kidneys?', 'Filter blood, reabsorb useful substances, and remove urea, excess water and ions as urine, controlling water balance.', 18),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'Where is urea produced and why?', 'In the liver, from the breakdown of excess amino acids (deamination); it is toxic and must be excreted.', 19),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'What is ultrafiltration in the kidney?', 'Blood at high pressure forces small molecules (water, glucose, ions, urea) out of the glomerulus into the nephron; proteins and cells stay in blood.', 20),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'What is selective reabsorption?', 'Useful substances are reabsorbed into the blood from the nephron: all glucose (by active transport), some ions and water as needed.', 21),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'Why is there normally no glucose or protein in urine?', 'Proteins are too large to be filtered; all glucose is reabsorbed back into the blood.', 22),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'What is ADH and where is it released?', 'Antidiuretic hormone, released by the pituitary gland, which controls the amount of water reabsorbed in the kidneys.', 23),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'What happens to ADH when blood is too concentrated?', '(Higher) More ADH is released, collecting ducts become more permeable, more water is reabsorbed, giving a small volume of concentrated urine.', 24),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'How do the kidneys respond if you drink a lot of water?', '(Higher) Less ADH is released, less water is reabsorbed, so a large volume of dilute urine is produced.', 25),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'How do alcohol and ecstasy affect urine production?', '(Higher) Alcohol suppresses ADH, causing dilute urine and dehydration; ecstasy increases ADH, producing concentrated urine and risk of water retention.', 26),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'How does kidney dialysis work?', 'Blood flows past a partially permeable membrane in dialysis fluid with normal blood levels of glucose and ions; urea and excess ions diffuse out.', 27),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'Give one advantage and one disadvantage of a kidney transplant compared with dialysis.', 'Advantage: long-term solution, no regular sessions. Disadvantage: risk of rejection, needs immunosuppressant drugs, shortage of donors.', 28),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'How does exercise on a hot day affect water balance?', 'More sweating increases water loss, so less water is lost in urine (more ADH) and urine is more concentrated.', 29),
  ('Biology', 'OCR B', 'gcse', 'B5.4', 'Maintaining a constant internal environment', 'Practical: How could you investigate the effect of insulation on cooling?', 'Fill tubes with hot water, wrap with different layers of insulation, measure temperature every minute; keep volume and start temperature the same.', 30),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'What is evolution?', 'The gradual change in the inherited characteristics of a population over many generations, which may lead to new species.', 1),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'What was Lamarck''s theory of evolution?', 'Characteristics acquired during an organism''s lifetime (e.g. giraffes stretching necks) are passed on to offspring.', 2),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'Why was Lamarck''s theory rejected?', 'Acquired characteristics are not inherited because they do not change the DNA in sex cells; experiments did not support it.', 3),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'Who proposed the theory of evolution by natural selection?', 'Charles Darwin, with Alfred Russel Wallace who developed the idea independently.', 4),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'What did Darwin observe on the Galápagos Islands?', 'Species such as finches and tortoises varied between islands, with features (e.g. beak shape) suited to local food sources.', 5),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'When was On the Origin of Species published?', '1859, after Darwin and Wallace presented a joint paper in 1858.', 6),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'What was Wallace''s contribution to evolutionary theory?', 'He independently proposed natural selection, prompting Darwin to publish; he also studied warning colouration and speciation.', 7),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'Summarise Darwin''s theory of natural selection.', 'Individuals vary; more offspring are produced than survive; those best suited survive and reproduce, passing on characteristics; over generations the species changes.', 8),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'Give three reasons Darwin''s theory was slow to be accepted.', 'It challenged the religious belief that God created all species; there was too little evidence; the mechanism of inheritance (genes) was unknown.', 9),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'How did Mendel''s work later support Darwin''s theory?', 'It explained how characteristics are inherited as discrete units (genes), providing the missing mechanism.', 10),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'What is a fossil?', 'The preserved remains or traces of an organism from many thousands or millions of years ago, usually found in rock.', 11),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'Describe three ways fossils can form.', 'Hard parts replaced by minerals; parts preserved where decay cannot happen (ice, amber, peat bogs); traces such as footprints or burrows preserved in rock.', 12),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'Why is the fossil record incomplete?', 'Soft-bodied organisms rarely fossilise, conditions for fossilisation are rare, many fossils were destroyed by geological activity, and many are undiscovered.', 13),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'How do fossils provide evidence for evolution?', 'Rock layers show organisms changing gradually over time, with simpler forms in older layers and more complex ones in younger layers.', 14),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'How does the evolution of the horse support evolution?', 'Fossils show gradual change from a small, multi-toed forest animal to a large, single-hoofed grassland grazer.', 15),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'Why is it hard to find evidence of the earliest life forms?', 'They were mostly soft-bodied so left few traces, and old traces have been destroyed by geological activity.', 16),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'What is a pentadactyl limb and why is it evidence for evolution?', 'A five-digit limb structure shared by many vertebrates (e.g. human arm, bat wing, whale flipper), suggesting a common ancestor.', 17),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'How does DNA evidence support evolution?', 'Closely related species have more similar DNA base sequences, confirming relationships suggested by fossils and anatomy.', 18),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'How does antibiotic resistance support Darwin''s theory?', 'It shows natural selection happening rapidly: resistant bacteria survive and reproduce while susceptible ones die.', 19),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'What is an evolutionary tree?', 'A diagram showing how species are related and descended from common ancestors, based on fossil, anatomical and DNA evidence.', 20),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'What is a common ancestor?', 'A species from which two or more different species have evolved.', 21),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'What is classification?', 'Organising living organisms into groups based on their shared characteristics and evolutionary relationships.', 22),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'List Linnaeus''s taxonomic groups in order.', 'Kingdom, phylum, class, order, family, genus, species.', 23),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'What is the binomial naming system?', 'Giving each species a two-part Latin name: genus then species, e.g. Homo sapiens.', 24),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'Why is the binomial system useful?', 'Scientists worldwide use the same unambiguous name for each species, avoiding confusion from local common names.', 25),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'What is the three-domain system and who proposed it?', 'Carl Woese divided life into Archaea, Bacteria and Eukaryota based on chemical analysis (e.g. RNA sequences).', 26),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'Why have classification systems changed over time?', 'New evidence from microscopes, biochemistry and DNA sequencing revealed relationships not visible from appearance alone.', 27),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'What is a species?', 'A group of similar organisms that can interbreed to produce fertile offspring.', 28),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'How does peer review help scientific theories become accepted?', 'Other scientists check methods and conclusions before publication, and findings are repeated, building confidence in the evidence.', 29),
  ('Biology', 'OCR B', 'gcse', 'B6.1', 'How the theory of evolution was developed', 'How did Darwin''s theory change over time?', 'It was combined with genetics and DNA evidence to form the modern theory, explaining variation by mutation and allele inheritance.', 30),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'What causes genetic variation within a species?', 'Mutations in DNA and the mixing of alleles through sexual reproduction (meiosis and random fertilisation).', 1),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'What is environmental variation?', 'Differences caused by surroundings or lifestyle (e.g. scars, tan, language); not inherited.', 2),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'What is a mutation?', 'A random change in the base sequence of DNA; the only source of new alleles.', 3),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'Do most mutations affect the phenotype?', 'No; most have no effect. A few are harmful and very rarely one is beneficial in a particular environment.', 4),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'How can a mutation lead to a new phenotype?', '(Higher) It changes the base sequence, which can change the amino acid sequence and so the shape and function of a protein.', 5),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'What is a selection pressure?', 'An environmental factor, such as predation, disease, competition or climate, that affects which individuals survive and reproduce.', 6),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'Describe the steps of natural selection.', 'Variation exists; selection pressure acts; better-adapted individuals survive and reproduce; they pass on their alleles; advantageous alleles become more common over generations.', 7),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'Why must natural selection answers avoid saying organisms adapt deliberately?', 'Individuals cannot choose to change; the variation already exists through mutation and is selected by the environment.', 8),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'Explain the evolution of antibiotic-resistant bacteria.', 'A random mutation gives resistance; antibiotic kills susceptible bacteria; resistant ones survive and reproduce; the resistant population grows.', 9),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'Why do bacteria evolve resistance quickly?', 'They reproduce very rapidly, so many generations occur in a short time; resistance genes can also spread on plasmids.', 10),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'How can the spread of antibiotic resistance be reduced?', 'Not overprescribing antibiotics, finishing the course, restricting agricultural use, good hygiene in hospitals.', 11),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'Explain how peppered moths evolved during the Industrial Revolution.', 'Soot darkened trees; dark moths were better camouflaged so fewer were eaten by birds; they survived to breed, so the dark allele increased.', 12),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'What are Darwin''s finches an example of?', 'Adaptive radiation: beak shapes evolved to suit different food sources on different islands, forming separate species.', 13),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'What is an allele frequency?', '(Higher) The proportion of a particular allele in a population''s gene pool; natural selection changes allele frequencies over time.', 14),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'What is speciation?', 'The formation of a new species when populations become so different they can no longer interbreed to produce fertile offspring.', 15),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'Describe the process of geographic (allopatric) speciation.', 'Populations are separated by a barrier; different mutations and selection pressures act on each; over time they become reproductively isolated and form new species.', 16),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'Give two types of barrier that can isolate populations.', 'Geographical (mountains, rivers, seas) and behavioural or reproductive (different mating seasons or courtship displays).', 17),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'What is reproductive isolation?', 'When two populations can no longer interbreed to produce fertile offspring.', 18),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'Why are mules not a separate species?', 'Mules (horse × donkey) are infertile, so they cannot breed to produce offspring.', 19),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'What is extinction?', 'When no individuals of a species remain alive anywhere.', 20),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'Give four causes of extinction.', 'New predators, new diseases, more successful competitors, habitat destruction, climate change, a catastrophic event such as an asteroid impact.', 21),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'Why can a change in the environment lead to extinction?', 'If the species cannot adapt quickly enough (too little variation or slow reproduction), individuals fail to survive and reproduce.', 22),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'What is selective breeding?', 'Humans choose parents with desired characteristics to breed together over many generations (artificial selection).', 23),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'How does selective breeding differ from natural selection?', 'In selective breeding humans choose which characteristics are passed on; in natural selection the environment determines which individuals survive.', 24),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'Give one risk of selective breeding.', 'Inbreeding reduces genetic variation, increasing the risk of inherited disorders and vulnerability to disease or environmental change.', 25),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'Why is genetic variation important for a species'' survival?', 'It increases the chance some individuals have characteristics to survive environmental change or new disease.', 26),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'What is genetic engineering and how does it differ from selective breeding?', 'Directly transferring genes between organisms; it is faster and can cross species barriers, whereas selective breeding works within a species over generations.', 27),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'Why can new species of bacteria and insects evolve faster than mammals?', 'They have short generation times and produce huge numbers of offspring, giving more mutations and faster selection.', 28),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'What is the role of chance in evolution?', 'Mutations occur randomly, and which individuals survive events such as disasters can be random, affecting allele frequencies.', 29),
  ('Biology', 'OCR B', 'gcse', 'B6.2', 'How evolution takes place', 'How would you show evidence that a population has evolved?', 'Record changes in the frequency of a characteristic or allele across many generations (e.g. sampling moth colour or bacterial resistance).', 30),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'What is biodiversity?', 'The variety of all the different species of organisms on Earth or within an ecosystem, including genetic variety within species.', 1),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'Why is high biodiversity important?', 'It makes ecosystems more stable, reduces dependence on single species for food, shelter and ecosystem services, and provides resources such as medicines.', 2),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'What is an ecosystem service? Give two examples.', 'A benefit humans gain from ecosystems, e.g. pollination of crops, clean water, nutrient recycling, flood control, carbon storage.', 3),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'How does human population growth affect biodiversity?', 'More land, water and resources are used, more waste and pollution produced, reducing habitats and species.', 4),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'How does deforestation reduce biodiversity?', 'Destroys habitats and food sources, reduces species diversity, and less CO₂ is absorbed by trees, adding to climate change.', 5),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'Give two reasons for large-scale deforestation in tropical areas.', 'To provide land for cattle farming and rice fields, and to grow crops such as palm oil for food and biofuels.', 6),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'How does destroying peat bogs affect the environment?', 'Peat is burned as fuel or used as compost, releasing stored carbon as CO₂ and destroying habitats.', 7),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'What is eutrophication?', 'Fertiliser or sewage enters water; algae grow rapidly and block light; plants die; bacteria decomposing them use up oxygen, so fish and other animals die.', 8),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'What is bioaccumulation?', 'Build-up of toxic substances (e.g. pesticides, heavy metals) in organisms at higher concentrations further up a food chain.', 9),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'How does acid rain affect biodiversity?', 'Sulfur dioxide and nitrogen oxides form acid rain, which damages trees and makes lakes acidic, killing sensitive organisms.', 10),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'Name three greenhouse gases.', 'Carbon dioxide, methane and water vapour (also nitrous oxide).', 11),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'How does climate change affect biodiversity?', 'Changes in temperature and rainfall alter habitats; species distributions shift, migration patterns change and some species become extinct.', 12),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'How do invasive species reduce biodiversity?', 'They outcompete native species for resources, prey on them or spread disease, e.g. grey squirrels displacing red squirrels.', 13),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'How does overfishing affect biodiversity?', 'Fish populations fall faster than they can reproduce, disrupting food chains and possibly causing extinction.', 14),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'What are fishing quotas and why are they used?', 'Limits on the number and type of fish caught, allowing populations to recover so fishing is sustainable.', 15),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'How does mesh size of fishing nets help conservation?', 'Larger mesh lets young fish escape, so they can reach breeding age and maintain the population.', 16),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'What is meant by sustainable development?', 'Meeting the needs of people today without damaging the ability of future generations to meet their own needs.', 17),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'Give four ways to protect biodiversity.', 'Breeding programmes, protecting habitats (nature reserves), reintroducing hedgerows and field margins, reducing deforestation and recycling to cut landfill.', 18),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'Why are hedgerows and field margins reintroduced on farms?', 'They provide habitats and food for many species, increasing biodiversity in monoculture farmland.', 19),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'What are seed banks and why are they useful?', 'Stores of seeds from many plant species kept cold and dry, preserving genetic variation in case species become extinct in the wild.', 20),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'What are captive breeding programmes?', 'Breeding endangered species in zoos to increase numbers and genetic diversity, then reintroducing them into the wild.', 21),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'Give one problem with captive breeding programmes.', 'Small populations have low genetic diversity; animals may struggle to survive in the wild; it is expensive.', 22),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'What is CITES?', 'An international agreement restricting trade in endangered species and their products, e.g. ivory.', 23),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'Why might conservation schemes conflict with local people''s needs?', 'Protecting land may limit farming, logging or hunting that local communities depend on for income and food.', 24),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'How can food production be made more sustainable?', 'Reduce food waste, eat less meat, use sustainable fishing, develop high-yield crops, and use integrated pest management.', 25),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'Why is eating plants more efficient than eating meat?', 'Energy is lost at each trophic level, so less land is needed to feed people on plants than on livestock.', 26),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'What is a monoculture and how does it affect biodiversity?', 'Growing a single crop over a large area; it reduces habitat variety and the number of species supported.', 27),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'Practical: How can you use quadrats to compare biodiversity in two areas?', 'Place quadrats randomly in each area, count species and individuals in each, calculate means and compare species richness.', 28),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'Practical: How do you estimate population size from quadrat data?', 'Mean number per quadrat ÷ quadrat area × total area of the habitat.', 29),
  ('Biology', 'OCR B', 'gcse', 'B6.3', 'How biodiversity is affected', 'A 0.25 m² quadrat averages 6 daisies; the field is 400 m². Estimate the daisy population.', '6 ÷ 0.25 = 24 per m²; 24 × 400 = 9600 daisies.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Biology' AND exam_board = 'OCR B' AND level = 'gcse'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;
